using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{
Material Make(string name,string tex,bool alpha){string path="Assets/Materials/VisualRefinement/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m)return m;m=new Material(Shader.Find("Standard"));m.name=name;m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Art/Environment/Vegetation/Trees/Pines/PineDead_001/Materials/"+tex+".tif");if(!m.mainTexture)throw new Exception("texture missing");m.enableInstancing=true;m.SetFloat("_Glossiness",.04f);if(alpha){m.SetFloat("_Mode",1);m.SetFloat("_Cutoff",.3f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}AssetDatabase.CreateAsset(m,path);return m;}
public void Execute(ExecutionResult result){var stump=Make("DeadPine_Stump","stump_Albedo",false);var trunk=Make("DeadPine_Trunk","trunk_Albedo",false);var branches=Make("DeadPine_Branches","dead_branches_albedo",true);AssetDatabase.SaveAssets();var s=SceneManager.GetActiveScene();var r=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).First(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.name=="PineDead_03_LOD0");var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Art/Environment/Vegetation/Trees/Pines/PineDead_001/PineDead_03.prefab");var original=model.GetComponentsInChildren<Renderer>(true).First(x=>x.name==r.name);result.Log("source slots="+string.Join(";",original.sharedMaterials.Select(m=>m?m.name:"NULL")));var b=r.bounds;var go=new GameObject("__QA");var c=go.AddComponent<Camera>();c.fieldOfView=50;c.transform.position=b.center+new Vector3(b.size.y*.7f,0,-b.size.y*.8f);c.transform.LookAt(b.center);MMSequentialEvidence.Render(c,"Validation/VisualRefinement/deadpine_before.png",900,900);var old=r.sharedMaterials;r.sharedMaterials=new[]{stump,trunk,branches};MMSequentialEvidence.Render(c,"Validation/VisualRefinement/deadpine_preview.png",900,900);r.sharedMaterials=old;UnityEngine.Object.DestroyImmediate(go);result.Log("Preview restored");}}
